using Mapping=ModelMaterialDrawMappingCandidate;
static std::string description(const Mapping&m){std::ostringstream o;o<<m.checksum<<' '<<m.skinFamily<<' '<<m.body;for(const auto&r:m.ranges)o<<" R "<<r.range<<' '<<r.rendererMaterial<<' '<<r.textureIndex<<' '<<r.visit<<' '<<r.group;for(const auto&g:m.groups){o<<" G "<<g.material;for(auto v:g.visits)o<<" V "<<v;for(auto r:g.ranges)o<<" D "<<r;}for(auto g:m.visitGroups)o<<" P "<<g;for(const auto&v:m.rendererMaterialVisits){o<<" M";for(auto n:v)o<<' '<<n;}return o.str();}
static SfmModelGeometryCandidate mappingGeometry(){SfmModelGeometryCandidate g;g.checksum=77;g.materials.names={"a","b","a"};g.materials.directories={"models/test/"};g.materials.skins={{0,1,2},{1,0,2}};g.bodyModelCounts={2};g.bodyBases={1};g.geometry.vertices.resize(3);for(uint32_t i=0;i<4;++i){SfmModelMeshGeometryCandidate mesh;mesh.mesh=i;mesh.material=i==3?2:i==2?0:int32_t(i);mesh.triangles.push_back({i%3,(i+1)%3,(i+2)%3});g.meshes.push_back(mesh);}SfmModelMeshGeometryCandidate other;other.model=1;other.material=1;other.triangles={{{2,1,0}}};g.meshes.push_back(other);return g;}
static ModelRenderInputsCandidate mappingInputs(const SfmModelGeometryCandidate&geometry,uint32_t skin,uint32_t body){ModelRenderInputsCandidate out;std::map<std::string,uint32_t>loaded;for(const auto&mesh:geometry.meshes){if(mesh.model!=(body/geometry.bodyBases.at(mesh.body))%geometry.bodyModelCounts.at(mesh.body))continue;const auto&name=geometry.materials.resolve(skin,mesh.material);auto found=loaded.find(name);if(found==loaded.end()){auto slot=uint32_t(out.materials.size());found=loaded.emplace(name,slot).first;ModelRenderMaterialCandidate m;m.source.vmt=std::filesystem::path("C:/authored-mount/materials/models/test")/(name+".vmt");out.materials.push_back(std::move(m));}out.ranges.push_back({uint32_t(out.indices.size()),uint32_t(mesh.triangles.size()*3),found->second,mesh.body,mesh.model,mesh.mesh,-1});for(const auto&t:mesh.triangles)out.indices.insert(out.indices.end(),t.begin(),t.end());}return out;}
