 {auto body=mappingInputs(geometry,0,1);auto names=modelRenderMaterialKeysCandidate(body,{"C:/authored-mount"});StudioProxyPrebindPlanCandidate visits;visits.visits={{1,b,false}};check(names&&modelMaterialDrawMappingCandidate(geometry,0,1,body,*names,visits,map)&&map.ranges.size()==1&&map.ranges[0].textureIndex==1&&map.oneVisitPerMaterial()&&map.oneVisitPerRendererMaterial(),"bodygroup selects different model and mesh mapping");}
