 auto refuse=[&](const auto&g,uint32_t skin,uint32_t body,const auto&render,const auto&names,const auto&visits){auto out=sentinel;check(!modelMaterialDrawMappingCandidate(g,skin,body,render,names,visits,out)&&description(out)==old,"invalid association preserves complete old mapping");};
 for(unsigned mode=0;mode<9;++mode){auto bad=input;if(mode==0)bad.indices[0]=2;if(mode==1)bad.indices.pop_back();if(mode==2)bad.ranges[0].indexCount=2;if(mode==3)bad.ranges[1].firstIndex=0;if(mode==4)bad.ranges[0].materialIndex=1;if(mode==5)bad.ranges[0].mesh=99;if(mode==6)bad.ranges.push_back(bad.ranges[0]);if(mode==7)bad.ranges[1].mesh=bad.ranges[0].mesh;if(mode==8){bad.materials.push_back({});auto names=*keys;names.push_back("models/test/unused");refuse(geometry,0,0,bad,names,plan);continue;}refuse(geometry,0,0,bad,*keys,plan);}
 for(unsigned mode=0;mode<5;++mode){auto bad=plan;if(mode==0)std::swap(bad.visits[0],bad.visits[1]);if(mode==1)bad.visits[0].textureIndex.reset();if(mode==2)bad.visits[1].textureIndex=0;if(mode==3)bad.visits[0].material=0;if(mode==4)bad.visits.pop_back();refuse(geometry,0,0,input,*keys,bad);}
 for(unsigned mode=0;mode<7;++mode){auto bad=geometry;if(mode==0)bad.bodyBases[0]=0;if(mode==1)bad.bodyModelCounts[0]=0;if(mode==2)bad.meshes[0].mesh=7;if(mode==3)bad.meshes.push_back(bad.meshes[0]);if(mode==4)bad.meshes[0].material=-1;if(mode==5)bad.materials.skins[0][0]=99;if(mode==6)bad.meshes[0].triangles[0][0]=3;refuse(bad,0,0,input,*keys,plan);}
 {auto names=*keys;names[0]="MODELS/TEST/A";refuse(geometry,0,0,input,names,plan);names=*keys;names.pop_back();refuse(geometry,0,0,input,names,plan);refuse(geometry,0,UINT32_MAX,input,*keys,plan);refuse(geometry,UINT32_MAX,0,input,*keys,plan);check(modelMaterialDrawMappingCandidate(geometry,999,0,input,*keys,plan,map)&&map.skinFamily==0,"invalid positive skin uses native prebind family-zero fallback");}
 unsigned failures=0;bool complete=false;for(int64_t n=0;n<2048;++n){const auto balance=heapNew-heapDelete;bool ok=false;{auto trial=sentinel;failAfter=n;ok=modelMaterialDrawMappingCandidate(geometry,0,0,input,*keys,plan,trial);failAfter=-1;if(!ok){++failures;check(description(trial)==old,"actual allocation failure never publishes partial mapping");}else check(trial.groups[0].visits==std::vector<size_t>{0,2},"allocation sweep completes alias-aware mapping");}check(heapNew-heapDelete==balance,"mapping allocation cleanup");if(ok){complete=true;break;}}check(complete&&failures>0,"actual mapping allocation sweep covered");
 std::cout<<"PASS model_material_mapping_checks="<<checks<<" actual_allocation_failures="<<failures<<" alias_groups=PASS topology=EXACT queued_snapshot_policy=UNVERIFIED renderer_admission=NOT_CONNECTED\n";return 0;
