static std::vector<uint8_t>mappingReadBytes(const std::filesystem::path&p){std::ifstream in(p,std::ios::binary);need(bool(in),"read-only original input");return std::vector<uint8_t>((std::istreambuf_iterator<char>(in)),{});}
static std::string mappingReadText(const std::filesystem::path&p){auto bytes=mappingReadBytes(p);return {bytes.begin(),bytes.end()};}
