 Store store;MaterialObjectParameterOptionsCandidate options;options.proxyFactory=std::make_shared<MaterialPinnedClientIfmProxyFactoryCandidate>();options.provider=[&](const std::string&name)->std::optional<std::string>{auto key=sourceMaterialKeyValuesPathCandidate(name);for(const auto&mount:mounts)if(std::filesystem::is_regular_file(mount/key))return mappingReadText(mount/key);return {};};MaterialSessionFileRuntimeCandidate runtime(store,options);std::vector<ModelMaterialResourceBindingCandidate>bindings;std::vector<Store::Id>ids;
 for(const auto&name:geometry.materials.names){std::optional<Store::Id>id;for(const auto&dir:geometry.materials.directories){auto path=materialRelativePathCandidate(dir+name,".vmt");std::string key;if(materialFindCacheKeyCandidate(path.generic_string(),key)){id=runtime.findMaterial(key);if(id)break;}}need(id&&runtime.initialize(*id)&&store.increment(*id),"actual retained material profile");auto binding=ModelMaterialResourceBindingCandidate::checked(store,*id);need(bool(binding),"checked actual filename resource");ids.push_back(*id);bindings.push_back(*binding);}
 Mapping mapping;MaterialProxyEvaluationInputsCandidate time;time.currentTimeBits=0x3e000000;unsigned calls=0;need(withModelMaterialPrebindDrawCandidate(store,graph,model,model.placement.asset,geometry,bindings,{},time,[&](const auto&view){++calls;return modelMaterialDrawMappingCandidate(geometry,model.skin,model.body,renderer,*keys,view.selection,mapping);}),"actual model prebind-to-renderer topology mapping");need(calls==1&&mapping.groups.size()==2&&mapping.oneVisitPerMaterial()&&mapping.oneVisitPerRendererMaterial()&&mapping.ranges[0].textureIndex==2&&mapping.ranges[1].textureIndex==1,"actual blue weapon/pilot texture association");
 std::vector<const MaterialObjectParameterStateCandidate*>pointers;std::vector<std::string>saved;for(auto id:ids){pointers.push_back(store.get(id)->parameterState.get());saved.push_back(snapshot(store,id));}auto bad=renderer;bad.indices[0]^=1;need(!withModelMaterialPrebindDrawCandidate(store,graph,model,model.placement.asset,geometry,bindings,{},time,[&](const auto&view){return modelMaterialDrawMappingCandidate(geometry,model.skin,model.body,bad,*keys,view.selection,mapping);}),"bad renderer association aborts actual material transaction");for(size_t i=0;i<ids.size();++i)need(store.get(ids[i])->parameterState.get()==pointers[i]&&snapshot(store,ids[i])==saved[i]&&!store.get(ids[i])->sessionPending,"actual mapping refusal preserves material pointers and values");
 for(const auto&r:mapping.ranges)std::cout<<"RANGE\t"<<r.range<<'\t'<<r.rendererMaterial<<'\t'<<r.textureIndex<<'\t'<<r.visit<<'\t'<<(*keys)[r.rendererMaterial]<<'\t'<<renderer.ranges[r.range].indexCount<<'\n';for(auto id:ids)need(store.decrement(id),"release actual material references");std::cout<<"PASS actual_model=13817 mapped_ranges="<<mapping.ranges.size()<<" resource_groups="<<mapping.groups.size()<<" triangle_indices="<<renderer.indices.size()<<" topology=EXACT refusal_rollback=PASS queued_snapshot_policy=UNVERIFIED GPU=NOT_RUN\n";return 0;
